<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientTosUriAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientTosUriAccessor trait.
 *
 * Covers null default, string/VO assignment via withTosUri,
 * getTosUri/tosUri accessors, and isTosUriChanged with/without original.
 */
class TrustedClientTosUriAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTosUri creates a new instance with the TosUri set
     * from a string value, and getTosUri returns the primitive string.
     */
    public function testWithTosUriFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTosUriAccessorUnitTest();

        // Act
        $result = $holder->withTosUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getTosUri());
    }
    /**
     * Asserts that withtosUri has access to the value object
     * from a string value, and getTosUri returns the primitive string.
     */
    public function testWithTosUriFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTosUriAccessorUnitTest();

        // Act
        $result = $holder->withTosUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->tosUri()->value());
    }
    public function testChangedTosUri(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTosUriAccessorUnitTest();
        $original = $holder->withTosUri('one');
        $same = $holder->withTosUri('one');
        $modified = $holder->withTosUri('other');

        // Act
        $unchanged = $holder->isTosUriChanged();
        $withSame = $original->isTosUriChanged($same);
        $withDiferent = $original->isTosUriChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientTosUriAccessorUnitTest
{
    use TrustedClientTosUriAccessor;
}
